parameters.jsCode:
const contact = $('Loop Each Contact').first().json;

let brave = [];
try { const b = $('Pass 1 - Brave Resolve').first().json; brave = (b && b.web && Array.isArray(b.web.results)) ? b.web.results.slice(0, 5).map(r => ({ title: r.title, url: r.url, description: r.description })) : []; } catch (e) { brave = []; }

let publicVoice = '';
try { const p = $('Pass 2 - Perplexity Public Voice').first().json; publicVoice = (p && p.choices && p.choices[0] && p.choices[0].message) ? (p.choices[0].message.content || '') : ''; } catch (e) { publicVoice = ''; }

let threads = [];
try { threads = $('Pass 3 - Gmail Private Graph').all().map(i => ({ id: i.json.id, snippet: i.json.snippet })).filter(t => t && t.snippet); } catch (e) { threads = []; }
const hasEmail = !!(contact.email && String(contact.email).length > 3);

return [{ json: {
  contact,
  research: {
    brave_results: brave,
    public_voice: publicVoice,
    email_threads: hasEmail ? threads : [],
    private_graph_skipped: !hasEmail,
    calendar_skipped: true
  }
} }];

