const item = $input.first();
const blocks = (item.json && item.json.content) || [];
const text = Array.isArray(blocks) ? blocks.map(b => b.text || '').join('\n').trim() : '';
let cross = null;
try { const a = text.indexOf('{'); const b = text.lastIndexOf('}'); if (a >= 0 && b > a) cross = JSON.parse(text.slice(a, b + 1)); } catch (e) { cross = null; }
const ctx = $('Assemble Research Context').first().json;
return [{ json: { contact: ctx.contact, research: ctx.research, cross_venture: cross || { per_venture_angle: [], strongest_venture: null, parse_failed: true } } }];

