const item = $input.first();
const blocks = (item.json && item.json.content) || [];
const text = Array.isArray(blocks) ? blocks.map(b => b.text || '').join('\n').trim() : '';
let weapon = null;
try { const a = text.indexOf('{'); const b = text.lastIndexOf('}'); if (a >= 0 && b > a) weapon = JSON.parse(text.slice(a, b + 1)); } catch (e) { weapon = null; }
const prev = $('Parse Cross-Venture').first().json;
const contact = prev.contact;
const dossier = {
  generated_at: new Date().toISOString(),
  engine: 'RE Dossier Engine v1',
  model: 'claude-sonnet-4-6',
  pass1_resolve: prev.research.brave_results || [],
  pass2_public_voice: prev.research.public_voice || '',
  pass3_private_graph: { email_threads: prev.research.email_threads || [], skipped: !!prev.research.private_graph_skipped, calendar_skipped: !!prev.research.calendar_skipped },
  pass4_cross_venture: prev.cross_venture || {},
  pass5_meeting_weapon: weapon || { parse_failed: true }
};
return [{ json: { id: contact.id, full_name: contact.full_name || '', dossier, meeting_weapon: weapon || {} } }];
